import { type ReactNode } from "react";
import { cn } from "@/lib/cn";

// Stands in the footprint of a control that cannot work now.
// Plain text: no role, no tabindex, no hover or press, no disabled look. The title is a paragraph, never a heading.

export type InertReasonBlockProps = {
  /** The missing action's own icon, for example <ArrowLeftRight />. Decorative. */
  icon: ReactNode;
  /** The action's name plus "not available", for example "Swap is not available". */
  title: string;
  /** One sentence naming the cause. Supply a lang-marked span for a role name in another script. Without it nothing renders. */
  reason: ReactNode;
  className?: string;
};

export function InertReasonBlock({ icon, title, reason, className }: InertReasonBlockProps) {
  if (!reason || (typeof reason === "string" && reason.trim() === "")) return null;
  return (
    <div
      className={cn(
        "flex min-h-control w-full items-start gap-gap-sm rounded-control border-bw-default border-border bg-surface-sunken p-inset-md",
        className,
      )}
    >
      <span aria-hidden="true" className="inline-flex size-icon-lg shrink-0 text-text-muted [&>svg]:size-full">
        {icon}
      </span>
      <div className="flex min-w-0 flex-col gap-stack-sm font-body text-ui-reading leading-normal [overflow-wrap:anywhere]">
        <p className="font-medium text-text">{title}</p>
        <p className="font-regular text-text-muted">{reason}</p>
      </div>
    </div>
  );
}
